using lab1.Model.StaticValues;using lab1.Model.Strategies;namespace lab1.Main;public class Application{    private static Object _lock = new ();    private static int _numIter = 10000;        public static void Main(string[] args)    {        if (args.Length == 0)        {            Func1();        }        else        {            switch (args[0])            {                case "2": Func2(); break;                case "3": Func3(); break;                default: Func1(); break;            }        }    }    private static void Func1()    {        var types = typeof(ISkipStrategy)            .Assembly            .GetTypes()            .Where(t => typeof(ISkipStrategy).IsAssignableFrom(t) &&                        t is { IsClass: true, IsAbstract: false })            .Select(t => (ISkipStrategy)Activator.CreateInstance(t))            .ToList();            for (var i = 0; i < types.Count; i++)        {            Console.WriteLine(i + ": " + types[i]?.Name);        }            Console.Write("Enter the ISkipStrategy number that will be used in the program: ");            var line = Console.ReadLine();        Console.WriteLine();        if (line != null && Int32.TryParse(line, out var number) && number >= 0 && number < types.Count)        {            var controller = new Controller.Controller(types[number] ?? new AlwaysTrueSkipStrategy());            if (controller.Simulate())            {                Console.WriteLine("The student departed on " + (StaticValues.Day + 1) + " day.");            }            controller.PrintResult();        }    }        private static void Func2()    {        var types = typeof(ISkipStrategy)            .Assembly            .GetTypes()            .Where(t => typeof(ISkipStrategy).IsAssignableFrom(t) &&                        t is { IsClass: true, IsAbstract: false })            .Select(t => (ISkipStrategy)Activator.CreateInstance(t))            .ToList();            for (var i = 0; i < types.Count; i++)        {            Console.WriteLine(i + ": " + types[i]?.Name);        }            Console.Write("Enter the ISkipStrategy number that will be used in the program: ");            var line = Console.ReadLine();        Console.WriteLine();        if (line != null && Int32.TryParse(line, out var number) && number >= 0 && number < types.Count)        {            var pleasure = 0;            var counterDemanded = 0;            for (var i = 0; i < 1000; i++)            {                types = typeof(ISkipStrategy)                    .Assembly                    .GetTypes()                    .Where(t => typeof(ISkipStrategy).IsAssignableFrom(t) &&                                t is { IsClass: true, IsAbstract: false })                    .Select(t => (ISkipStrategy)Activator.CreateInstance(t))                    .ToList();                var controller = new Controller.Controller(types[number] ?? new AlwaysTrueSkipStrategy());                if (controller.Simulate())                {                    counterDemanded++;                }                pleasure += controller.PrintResult();                Console.WriteLine();                StaticValues.ResetDay();            }                        Console.WriteLine(((double)pleasure) / 100000.0);        }    }        private static void Func3()    {        for (var k = 2; k <= 50; k += 1)        {            var printString = "";            for (var j = 0; j <= 100; j++)            {                var pleasure = 0;                for (var i = 0; i < _numIter; i++)                {                    var controller = new Controller.Controller(new MyNewSkipStrategy(j, ((double) k) / 10.0));                    controller.Simulate();                    pleasure += controller.GetResult();                    StaticValues.ResetDay();                }                printString += k + ";" + j + ";" + ((double)pleasure) / (100.0 * _numIter)  + "\n";            }            PrintString(printString);        }                PrintString("\n\n\n\n");                for (var k = 2; k <= 50; k += 1)        {            var printString = "";            for (var j = 0; j <= 100; j++)            {                var pleasure = 0;                for (var i = 0; i < _numIter; i++)                {                    var controller = new Controller.Controller(new MySkipStrategy(j, k));                    controller.Simulate();                    pleasure += controller.GetResult();                    StaticValues.ResetDay();                }                printString += k + ";" + j + ";" + ((double)pleasure) / (100.0 * _numIter)  + "\n";            }            PrintString(printString);        }    }    private static void PrintString(string str)    {        File.AppendAllText("output_new.csv", str);    }}